  "این حساب از قبل مالک پنل پروفایل پزشک دیگری است؛ اول آن را جدا کنید": {"en": "This account already owns another doctor profile panel; detach it first", "ar": "هذا الحساب يملك بالفعل لوحة أخرى من نوع «ملف الطبيب»؛ افصلها أولًا", "ur": "یہ اکاؤنٹ پہلے سے ایک اور ڈاکٹر پروفائل پینل کا مالک ہے؛ پہلے اسے الگ کریں", "tr": "Bu hesap zaten başka bir doktor profili panelinin sahibi; önce onu ayırın", "de": "Dieses Konto ist bereits Inhaber eines anderen Panels vom Typ „Arztprofil“; lösen Sie es zuerst", "fr": "Ce compte est déjà propriétaire d’un autre panneau de type « Profil de médecin » ; détachez-le d’abord", "es": "Esta cuenta ya es propietaria de otro panel de tipo «Perfil de médico»; desvincúlelo primero", "pt": "Esta conta já é responsável por outro painel do tipo “Perfil de médico”; desvincule-o primeiro", "ru": "Этот аккаунт уже владеет другой панелью типа «Профиль врача»; сначала отвяжите её", "zh": "该账户已是另一个医生主页面板的所有者；请先解除关联", "ja": "このアカウントはすでに別の医師プロフィールパネルの所有者です。先に解除してください", "hi": "यह खाता पहले से किसी अन्य डॉक्टर प्रोफ़ाइल पैनल का स्वामी है; पहले उसे अलग करें", "bn": "এই অ্যাকাউন্ট ইতিমধ্যে অন্য একটি ডাক্তার প্রোফাইল প্যানেলের মালিক; আগে সেটি আলাদা করুন", "id": "Akun ini sudah menjadi pemilik panel profil dokter lain; lepaskan dulu"},
  "این حساب از قبل مالک پنل کلینیک دیگری است؛ اول آن را جدا کنید": {"en": "This account already owns another clinic panel; detach it first", "ar": "هذا الحساب يملك بالفعل لوحة أخرى من نوع «العيادة»؛ افصلها أولًا", "ur": "یہ اکاؤنٹ پہلے سے ایک اور کلینک پینل کا مالک ہے؛ پہلے اسے الگ کریں", "tr": "Bu hesap zaten başka bir klinik panelinin sahibi; önce onu ayırın", "de": "Dieses Konto ist bereits Inhaber eines anderen Panels vom Typ „Klinik“; lösen Sie es zuerst", "fr": "Ce compte est déjà propriétaire d’un autre panneau de type « Clinique » ; détachez-le d’abord", "es": "Esta cuenta ya es propietaria de otro panel de tipo «Clínica»; desvincúlelo primero", "pt": "Esta conta já é responsável por outro painel do tipo “Clínica”; desvincule-o primeiro", "ru": "Этот аккаунт уже владеет другой панелью типа «Клиника»; сначала отвяжите её", "zh": "该账户已是另一个诊所面板的所有者；请先解除关联", "ja": "このアカウントはすでに別のクリニックパネルの所有者です。先に解除してください", "hi": "यह खाता पहले से किसी अन्य क्लिनिक पैनल का स्वामी है; पहले उसे अलग करें", "bn": "এই অ্যাকাউন্ট ইতিমধ্যে অন্য একটি ক্লিনিক প্যানেলের মালিক; আগে সেটি আলাদা করুন", "id": "Akun ini sudah menjadi pemilik panel klinik lain; lepaskan dulu"},
