  "این حساب از قبل مالک پنل مرکز پاراکلینیک دیگری است؛ اول آن را جدا کنید": {"en": "This account already owns another diagnostic center panel; detach it first", "ar": "هذا الحساب يملك بالفعل لوحة أخرى من نوع «مركز التشخيص»؛ افصلها أولًا", "ur": "یہ اکاؤنٹ پہلے سے ایک اور تشخیصی مرکز پینل کا مالک ہے؛ پہلے اسے الگ کریں", "tr": "Bu hesap zaten başka bir tanı merkezi panelinin sahibi; önce onu ayırın", "de": "Dieses Konto ist bereits Inhaber eines anderen Panels vom Typ „Diagnostikzentrum“; lösen Sie es zuerst", "fr": "Ce compte est déjà propriétaire d’un autre panneau de type « Centre de diagnostic » ; détachez-le d’abord", "es": "Esta cuenta ya es propietaria de otro panel de tipo «Centro de diagnóstico»; desvincúlelo primero", "pt": "Esta conta já é responsável por outro painel do tipo “Centro de diagnóstico”; desvincule-o primeiro", "ru": "Этот аккаунт уже владеет другой панелью типа «Диагностический центр»; сначала отвяжите её", "zh": "该账户已是另一个诊断中心面板的所有者；请先解除关联", "ja": "このアカウントはすでに別の検査センターパネルの所有者です。先に解除してください", "hi": "यह खाता पहले से किसी अन्य डायग्नोस्टिक केंद्र पैनल का स्वामी है; पहले उसे अलग करें", "bn": "এই অ্যাকাউন্ট ইতিমধ্যে অন্য একটি ডায়াগনস্টিক সেন্টার প্যানেলের মালিক; আগে সেটি আলাদা করুন", "id": "Akun ini sudah menjadi pemilik panel pusat diagnostik lain; lepaskan dulu"},
