  "استان و شهر این نقطه پیدا نشد؛ نقطه را دقیق‌تر روی نقشه بگذارید یا شهر را انتخاب کنید": {"en": "The province and city of this point weren't found; place the pin more precisely or choose the city", "ar": "لم يتم العثور على المحافظة والمدينة لهذه النقطة؛ ضع الدبوس بدقة أكبر أو اختر المدينة", "ur": "اس نقطے کا صوبہ اور شہر نہیں ملا؛ پن کو زیادہ درست رکھیں یا شہر منتخب کریں", "tr": "Bu noktanın ili ve şehri bulunamadı; işareti daha doğru koyun veya şehri seçin", "de": "Provinz und Stadt dieses Punkts wurden nicht gefunden; setzen Sie die Markierung genauer oder wählen Sie die Stadt", "fr": "La province et la ville de ce point sont introuvables ; placez le repère plus précisément ou choisissez la ville", "es": "No se encontraron la provincia y la ciudad de este punto; coloca el marcador con más precisión o elige la ciudad", "pt": "Não foram encontradas a província e a cidade deste ponto; posicione o marcador com mais precisão ou escolha a cidade", "ru": "Провинция и город этой точки не найдены; поставьте отметку точнее или выберите город", "zh": "未找到该点所在的省份和城市；请更精确地放置标记或选择城市", "ja": "この地点の州と市が見つかりません。ピンをより正確に置くか、市を選択してください", "hi": "इस बिंदु का प्रांत और शहर नहीं मिला; पिन को और सटीक रखें या शहर चुनें", "bn": "এই বিন্দুর প্রদেশ ও শহর পাওয়া যায়নি; পিনটি আরও সঠিক জায়গায় রাখুন বা শহর বেছে নিন", "id": "Provinsi dan kota titik ini tidak ditemukan; letakkan penanda dengan lebih tepat atau pilih kotanya"},
